BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT156-S2-Q19$batch11$ AND q.stimulus=$batch11$Geologist: As a spinning object's radius decreases, its rate of rotation increases; for example, figure skaters can twirl faster by bringing their arms closer to their sides. This law of physics helps to explain why, over the past decade, Earth's rate of rotation increased. For earthquakes have increased in number and severity during the past decade; and since immediately after an earthquake Earth's tectonic plates move toward the center of the earth, their movement causes Earth's radius to decrease.$batch11$ AND q.prompt=$batch11$Which one of the following, if true, would most undermine the geologist's explanation of why Earth's rate of rotation increased over the last decade?$batch11$ AND q.correct_choice=$batch11$B$batch11$) THEN RAISE EXCEPTION 'Question changed: PT156-S2-Q19'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch11$4ce5c003-1fb6-429d-b62b-63eec4bf1563$batch11$) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch11$4ce5c003-1fb6-429d-b62b-63eec4bf1563$batch11$) <> 4 THEN RAISE EXCEPTION 'Explanation changed: PT156-S2-Q19'; END IF; END $guard$;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Earth's rotation sped up over the past decade because more earthquakes shrank Earth's radius.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$A spinning object speeds up as its radius shrinks. Earthquakes increased in number and severity. Right after an earthquake, tectonic plates move toward Earth's center, shrinking the radius.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The geologist assumes the plate movement after earthquakes produced a net decrease in the radius. If other forces pushed the other way, the radius may not have shrunk at all, and the explanation falls apart.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Show the radius may not have shrunk overall.$batch11$)) v(position,label,body) WHERE e.id=$batch11$4ce5c003-1fb6-429d-b62b-63eec4bf1563$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
